"use client";
import React from "react";

const DisplayCards = ({ cards = [] }) => {
  return (
    <div className="flex min-h-[400px] w-full items-center justify-center py-12">
      <div className="w-full max-w-3xl px-4">
        {/* Grid container for stacked cards */}
        <div
          className="relative grid w-full"
          style={{
            gridTemplateColumns: "1fr 1fr 1fr",
            gridTemplateAreas: "\"stack stack stack\"",
          }}
        >
          {cards.map((card, index) => (
            <div
              key={index}
              className={`relative ${card.className || ""}`}
              style={{
                gridArea: "stack",
                zIndex: cards.length - index,
              }}
            >
              {/* Card background */}
              <div
                className="absolute inset-0 rounded-xl"
                style={{
                  background: card.bgGradient || "linear-gradient(135deg, #1a080a 0%, #2a1520 100%)",
                  border: "1px solid rgba(212, 175, 55, 0.2)",
                }}
              />

              {/* Outline effect using before pseudo */}
              <div
                className="absolute inset-0 rounded-xl pointer-events-none"
                style={{
                  border: "1px solid rgba(212, 175, 55, 0.3)",
                  background: "rgba(26, 8, 10, 0.7)",
                  opacity: card.showOutline !== false ? 1 : 0,
                  transition: "opacity 700ms ease",
                }}
              />

              {/* Card content */}
              <div className="relative z-10 p-6">
                {/* Icon */}
                <div
                  className="mb-4 flex h-10 w-10 items-center justify-center rounded-lg"
                  style={{
                    background: `${card.accentColor || "#d4af37"}20`,
                    color: card.accentColor || "#d4af37",
                  }}
                >
                  {card.icon}
                </div>

                {/* Badge */}
                <div className="mb-3">
                  <span
                    className="text-xs font-semibold uppercase tracking-wider px-2 py-1 rounded"
                    style={{
                      background: `${card.accentColor || "#d4af37"}20`,
                      color: card.accentColor || "#d4af37",
                    }}
                  >
                    {card.badge}
                  </span>
                </div>

                {/* Title */}
                <h3
                  className="text-lg font-semibold mb-2"
                  style={{ color: "#ffffff" }}
                >
                  {card.title}
                </h3>

                {/* Description */}
                <p className="text-sm leading-relaxed mb-4" style={{ color: "rgba(255,255,255,0.6)" }}>
                  {card.description}
                </p>

                {/* Date/Info */}
                <p className="text-xs" style={{ color: "rgba(255,255,255,0.4)" }}>
                  {card.date}
                </p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default DisplayCards;
